{
  "rules": [
    {
      "category": "rent_increase_limit",
      "title": "Costa-Hawkins exemption from local rent control",
      "requirement": "Local governments cannot impose rent control on exempt residential units, allowing landlords to establish initial and subsequent rental rates freely. This preemption applies to newly constructed units, single-family homes, and separately alienable condominiums.",
      "requirement_es": "Los gobiernos locales no pueden imponer control de alquileres en unidades residenciales exentas, lo que permite a los propietarios fijar libremente las tarifas de alquiler iniciales y posteriores. Esta exención se aplica a unidades de nueva construcción, viviendas unifamiliares y condominios enajenables por separado.",
      "key_value": {
        "label": "local rent control restriction",
        "value": "exempt from local rent caps"
      },
      "coverage_conditions": {
        "type": "OR",
        "clauses": [
          {
            "field": "certificate_of_occupancy_date",
            "operator": ">",
            "value": "1995-02-01",
            "note": "certificate of occupancy issued after February 1, 1995"
          },
          {
            "field": "property_type",
            "operator": "in",
            "value": [
              "single_family",
              "condominium"
            ],
            "note": "alienable separate from the title to any other dwelling unit or is a subdivided interest"
          }
        ]
      },
      "exemptions": [
        {
          "description": "Units where the owner agreed by contract with a public entity in exchange for financial assistance or density bonus incentives",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Units containing serious unabated health, safety, fire, or building code violations cited at least six months preceding the vacancy",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Single-family homes or condominiums where the preceding tenancy was terminated by notice under Section 1946.1 or via rent change notice under Section 827",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Condominiums not yet sold separately by the subdivider to a bona fide purchaser for value (with limited exceptions)",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": "2005-01-01",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "supersedes",
        "target_scope": "local",
        "source_language": "Notwithstanding any other provision of law, an owner of residential real property may establish the initial and all subsequent rental rates"
      },
      "penalty": null,
      "source_citation": "Cal. Civ. Code § 1954.52",
      "quote": {
        "chunk": "c1",
        "start_words": "Notwithstanding any other provision of law,",
        "end_words": "any of the following is true:"
      },
      "confidence": 0.95
    }
  ]
}
